from research_helpers import *
base='https://www.horiba.com/usa/semiconductor/products/'
groups=[('mass-flow-controller-and-module/','Mass-flow or fluid-control product.', ['CRITERION D700uF','CRITERION D700T','CRITERION D700MG','CRITERION D700WR','CRITERION DZ-100','CRITERION D500','SEC-Z700X Series','SEC-Z700S Series','SEC-Z500X Series','SEC-N100 Series','SEC-E Series','SEC-8000 F/D/E Series','UR-Z700 Series','FS-3000','EC-5000 Series']),('liquid-source-vaporization-system/','Liquid precursor delivery product.',['MV-2000','LSC Series','VC Series','LE Series','LU Series','LF-F/LV-F Series']),('pressure-control/','Wafer cooling or pressure-control product.',['GR-500 Series','GR-300 Series','PV Series']),('gas-monitoring-analyzer/','Process-gas monitoring instrument.',['LG-100 Series','Micropole System QL Series','IR-300 Series','IR-400 Series']),('vacuum-gauge/','Capacitance manometer.',['VG S Series']),('automated-system/','Wafer film or optical defect measurement system.',['Xtrology','PLATO Series','PLATO-MicroScan','MiPLATO-SiC','PLIMA-LED','OPM Series']),('particle-detection/','Semiconductor particle detection instrument.',['PD10-EX','PD10','RP-1']),('plasma-monitor-and-controller/','Plasma process optical monitoring instrument.',['EV 2.0 Series','EV-140C Series','RU-1000','OES-Star','PoliSpectra M116 MultiTrack','VU90','VS70-MC','VS20-VIS','iHR Series']),('non-contact-temperature-measurement/','Process infrared thermometer.',['IT-270','IT-470F-H','IT-480 Series']),('surface-analysis/','Semiconductor surface-analysis instrument.',['GD-Profiler 2','LabRAM HR Evolution','AFM Optical Platform','SmartSPM']),('thin-film-analysis/','Semiconductor thin-film analysis instrument.',['PyroSense Series','LEM Series','UVISEL Plus','Auto SE','XploRA Nano','LabRAM Odyssey Nano','UVISEL Plus In-Situ']),('defect-impurity-monitoring/','Semiconductor optical or X-ray defect analysis instrument.',['LabRAM Soleil','SMS','XGT-9000','XGT-9000SL']),('emission-analysis/','Fluorescence and absorbance spectrometer.',['Duetta'])]
ps=[];es=[]
for path,desc,names in groups:
 e=ev(base+path,'Official semiconductor category page reviewed; exact related-product labels captured. Cross-listings consolidated; no unsupported specifications or manufacturer attribution for third-party-origin products.')
 es.append(e)
 for name in names:ps.append(p('HORIBA '+name,desc,e,'commercial',roles=['commercial_partner'],typ='product',sector='semiconductors',sub='semiconductor_equipment'))
C=ev('https://www.horiba.com/usa/water-liquid/products/measurement-parameters-analyzers/chemical-concentration-analyzers/','Official chemical-monitor catalogue includes named semiconductor process monitors; concentration ranges not expanded into invented SKUs.')
for name in ['CS-1000','CS-900F','CS-900','CS-620F','CS-600F','CS-700','CS-100F1 Series','CS-100 Series','HF-700A','HF-960M','HF-960H','HF-960EM','HE-960H-TM-S','HE-960H-TM']:ps.append(p('HORIBA '+name,'Semiconductor chemical concentration monitor.',C,'commercial',roles=['commercial_partner'],typ='product',sector='semiconductors',sub='semiconductor_equipment'))
A=ev('https://www.horiba.com/usa/process-and-environmental/solutions/monitoring-of-airborne-molecular-contamination-in-clean-room-of-electronics-industry/','Official cleanroom semiconductor AMC application page identifies six exact monitor configurations, not assumed entire environmental catalogue relevance.')
for name,d in [('APNA-370','NOx monitor.'),('APNA-370/CU-2','Ammonia monitor configuration.'),('APSA-370','Sulfur-dioxide monitor.'),('APSA-370/CU-1','Hydrogen-sulfide monitor configuration.'),('APHA-370','Hydrocarbon monitor.'),('APOA-370','Ozone monitor.')]:ps.append(p('HORIBA '+name,d,A,'commercial',roles=['commercial_partner'],typ='product',sector='semiconductors',sub='semiconductor_equipment'))
es.extend([C,A]);assert len({x['canonical_name']for x in ps})==len(ps)
cs=[company('HORIBA Ltd',ps,es,'86 named semiconductor product models/families/configurations captured from reviewed official category catalogues; cross-listings merged and no fabricated range-derived SKUs. Roles conservatively indicate company-group commercial offering. Clinical diagnostics, biochemical instruments, semiconductor particle/ultrapure-water subsets, detail specifications, legacy and regional catalogue coverage remain incomplete.')]
(out/'batch-0058.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
